    super.initState();
    final initial = widget.initial;
    _nameController = TextEditingController(
      text: initial?.name ?? widget.prefillName ?? '',
    );
    _urlController = TextEditingController(
      text: initial?.baseUrl ?? widget.prefillBaseUrl ?? '',
