  final VoidCallback? onTap;

  @override
  Widget build(BuildContext context) {
    return Material(
      color: configured ? _onbSelBg(context) : _onbCard(context),
      borderRadius: BorderRadius.circular(16),
      child: InkWell(
        onTap: onTap,
